<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\OperationalTask; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class OperationalTaskController extends Controller { public function index(Request $request): JsonResponse { $items=OperationalTask::orderByRaw("CASE WHEN due_date IS NULL THEN 1 ELSE 0 END")->orderBy('due_date')->paginate($request->integer('per_page',25)); return ApiResponse::success($items->items(),null,['current_page'=>$items->currentPage(),'last_page'=>$items->lastPage(),'total'=>$items->total()]); } public function store(Request $request): JsonResponse { $data=$request->validate(['title'=>['required','string','max:255'],'description'=>['nullable','string','max:5000'],'due_date'=>['nullable','date'],'priority'=>['required',Rule::in(['low','normal','high'])]]); return ApiResponse::success(OperationalTask::create($data),'Task created.',[],201); } public function update(Request $request, OperationalTask $operationalTask): JsonResponse { $data=$request->validate(['status'=>['sometimes',Rule::in(['open','in_progress','completed'])],'title'=>['sometimes','string','max:255'],'description'=>['nullable','string','max:5000'],'due_date'=>['nullable','date'],'priority'=>['sometimes',Rule::in(['low','normal','high'])]]); $operationalTask->update($data); return ApiResponse::success($operationalTask->fresh()); } }
